<?php
declare(strict_types=1);
require_once __DIR__.'/seguridad.php';simceSecurityHeaders();
if(($_SERVER['REQUEST_METHOD']??'')!=='POST')simceJson(array('ok'=>false,'error'=>'Método no permitido.'),405);
$d=simceReadJson(65536);$action=(string)($d['action']??'login');
if($action==='logout'){simceRequireAdmin();simceRequireCsrf();simceDestroySession();simceJson(array('ok'=>true));}
if($action!=='login')simceJson(array('ok'=>false,'error'=>'Acción no válida.'),400);
