$user=trim((string)($d['usuario']??''));$password=(string)($d['password']??'');$schoolCode=strtolower(trim((string)($d['colegio']??'')));$school=false;
if($schoolCode!==''){$school=simceSchoolByCode($db,$schoolCode);if(!$school)simceJson(array('ok'=>false,'error'=>'Código de colegio, usuario o contraseña incorrectos.'),401);$s=$db->prepare("SELECT id,usuario,password_hash,rol,colegio_id FROM administradores WHERE colegio_id=:c AND usuario=:u AND activo=1 AND rol IN('colegio_admin','docente')");$s->execute(array(':c'=>$school['id'],':u'=>$user));}
else{$s=$db->prepare("SELECT id,usuario,password_hash,rol,colegio_id FROM administradores WHERE colegio_id IS NULL AND usuario=:u AND activo=1 AND rol='plataforma_superadmin'");$s->execute(array(':u'=>$user));}
$admin=$s->fetch();$context=$schoolCode?:'plataforma';$ip=simceClientIp();$now=time();$a=$db->prepare('SELECT intentos,bloqueado_hasta FROM intentos_login WHERE ip=:ip AND contexto=:ctx');$a->execute(array(':ip'=>$ip,':ctx'=>$context));$attempt=$a->fetch();if($attempt&&(int)$attempt['bloqueado_hasta']>$now)simceJson(array('ok'=>false,'error'=>'Demasiados intentos. Intenta más tarde.'),429);
if(!$admin||!password_verify($password,(string)$admin['password_hash'])){$failed=$attempt?(int)$attempt['intentos']+1:1;$until=$failed>=5?$now+900:0;if($attempt){$q=$db->prepare('UPDATE intentos_login SET intentos=:n,bloqueado_hasta=:b,actualizado_en=:t WHERE ip=:ip AND contexto=:ctx');}else{$q=$db->prepare('INSERT INTO intentos_login(intentos,bloqueado_hasta,actualizado_en,ip,contexto)VALUES(:n,:b,:t,:ip,:ctx)');}$q->execute(array(':n'=>$failed,':b'=>$until,':t'=>$now,':ip'=>$ip,':ctx'=>$context));usleep(350000);simceJson(array('ok'=>false,'error'=>'Código de colegio, usuario o contraseña incorrectos.'),401);}
